{
    vec2 uv = (fragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    float r = length(uv);
    float theta = atan(uv.y, uv.x);

    float time = iTime * 2.0;

    // Create spiral waves
    float wave = sin(theta * 10.0 + r * 20.0 - time);

    // Radial sine waves
    float radial = sin(r * 15.0 - time * 1.5);

    // Combine
    float pattern = 0.5 * wave + 0.5 * radial;
    pattern = (pattern + 1.0) / 2.0; // Remap to 0-1 range

    // Dynamic colors
    vec3 color1 = vec3(sin(time + 0.0) * 0.5 + 0.5, 
                      sin(time + 2.094) * 0.5 + 0.5,
                      sin(time + 4.188) * 0.5 + 0.5);

    vec3 color2 = vec3(cos(theta), radial, sin(r));

