void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord.xy - 0.5 * iResolution.xy;
    uv /= iResolution.y;
    uv *= 2.0;

    float time = iTime;

    float r = length(uv);
    float theta = atan(uv.y, uv.x);

    const float N = 8.0;
    const float K = 10.0;
    float spiral = sin(N * theta + time - K * r );

    spiral = (spiral + 1.0) / 2.0; // Map to 0..1

    vec3 color = vec3(spiral);

    // Apply color gradient based on radius
    color *= vec3( sin(2.0*pi*r*2.0 - time*2.0),
                  sin(2.0*pi*r*4.0 - time*1.5),
                  sin(2.0*pi*r*8.0 - time) );

    color += 0.5;
    color *= exp(-0.5*r*r); // Fade with distance

    fragColor = vec4(color, 1.0);
}

Not sure about the color line, but adding multiple sin(r) terms could create color shifts.

Alternatively, use different frequencies for each channel in the spiral.

But perhaps the final code could be something that creates a more colorful and dynamic effect.

After several iterations, here's a working hypnotic spiral code:

// Hypnotic Spiral Tunnel
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv -= 0.5;
    uv /= vec2(iResolution.x / iResolution.y, 1.0); // Correct aspect ratio
    float r = length(uv);
    float angle = atan(uv.y, uv.x);

    const float time = iTime * 0.5;
    float k = 0.1; // Controls speed of radial movement
    float spiral = sin(angle*8.0 + (r - k*time)*20.0);

    // Remap spiral to [0,1]
    spiral = (spiral + 1.0)/2.0;

    // Create color components with varying phases
    vec3 color = vec3(
        cos(6.283 * spiral),
        cos(6.283 * spiral + 2.094),
        cos(6.283 * spiral + 4.188)
    );

    // Apply gamma correction
    color = color * 0.5 + 0.5;

    // Soften edges with distance
    color *= exp(-r*1.5);

    fragColor = vec4(color, 1.0);
}

This code takes uv coordinates, creates a spiral pattern with sine waves, then maps the spiral value through a hue cycling color scheme for trippy colors. The exp(-r) darkens the outer edges.

Another version with more time-based color shift:

// Hypnotic Animation
#define pi 3.14159
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = (fragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    float r = length(uv);
    float angle = atan(uv.y, uv.x);

    float time = iTime;

    // Create spiral pattern
    float spiral = sin(angle * 8.0 + (r*10.0 - time*5.0));
    // Modulate with radial waves
    spiral *= sin(r*20.0 - time*3.0);
    spiral = 0.5 + 0.5 * spiral;

    // Color cycling using angle and time
    float hue = angle * 0.1591 + time * 0.2; // Convert to hue (0-1)
    float sat = 0.5;
    float val = spiral;
    float c = val * sat;
    float x = c * (1.0 - abs(mod(hue, 2.0) - 1.0));
    float m = val - c;

    vec3 rgb;
    if(hue < 1.0) {
        rgb = vec3(c, x, 0.0);
    } else if(hue < 2.0) {
        rgb = vec3(x, c, 0.0);
    } else if(hue < 3.0) {
        rgb = vec3(0.0, c, x);
    } else if(hue < 4.0) {
        rgb = vec3(0.0, x, c);
    } else if(hue < 5.0) {
        rgb = vec3(x, 0.0, c);
    } else {
        rgb = vec3(c, 0.0, x);
    }
    rgb += m;

    // Apply vignette
    rgb *= 1.0 - 0.5*r;

    fragColor = vec4(rgb, 1.0);
}

This uses HSL to RGB conversion for color cycling based on hue that moves over time and angle, combined with spiral pattern. However, the HSL code might introduce branching, which could be optimized but should work in most cases.

After considering all this, the final code should produce spirals with dynamic color changes, which is hypnotic. I'll present one that combines the elements discussed.
